module top_module(C, PRE, CLR, D, Q, CE);parameter INIT = 0; 
  input C, PRE, CLR, D, CE; 
  output reg Q; 
  initial begin 
  Q <= INIT; 
  end 
  always @(posedge C, negedge C, posedge PRE, posedge CLR) begin 
  if (CLR == 1) 
  Q <= 0; 
  else if (PRE == 1) 
  Q <= 1; 
  else if (CE == 1) 
  Q <= D; 
  end 
 endmodule

module top_module(A, B, SUB, SUM, CARRY);input [3:0] A;
input [3:0] B;
input SUB;
output reg [3:0] SUM; // Changed to reg to allow assignment in always block
output CARRY;

reg [3:0] twos_comp;
reg [4:0] temp_sum; // Changed to 5 bits to handle carry properly
reg carry;

always @(*) begin
    if(SUB == 1) begin
        twos_comp = ~B + 1;
        temp_sum = A + twos_comp;
        carry = temp_sum[4]; // Directly assign carry
        SUM = temp_sum[3:0];
    end
    else begin
        temp_sum = A + B;
        carry = temp_sum[4]; // Directly assign carry
        SUM = temp_sum[3:0];
    end
end

assign CARRY = carry;

endmodule

