module fsm (
    input clk,
    input reset,
    input a,
    output reg b);

    parameter S=0, T=1, U=2;
    reg [1:0] state, next;

    always @(posedge clk) begin
        if (reset) state <= S;
        else state <= next;
    end

    always_comb begin
        case (state)
            S: next = a ? T : S;
            T: next = a ? T : U;
            U: next = a ? T : S;
            default: next = 'x;
        endcase
    end

    assign b = (state == U);

endmodule

