description:
Design a 4-bit binary counter that increments its value on each positive edge of the clock signal. Upon receiving a reset signal (active low), the counter resets its output to zero.
module top_module(
  // inputs:
  clk,
  reset,

  // outputs:
  count
);

code:
module top_module(
  // inputs:
  clk,
  reset,

  // outputs:
  count
);// inputs
  input clk;
  input reset;

  // outputs
  output reg [3:0] count;

  // counter logic
  always @(posedge clk, negedge reset) begin
    if (!reset) begin
      count <= 4'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

