  input reset,
  input clk,
  output rst_sync
);

code:
module top_module(
  input reset,
  input clk,
  output rst_sync
);reg [1:0] sync_reset;

  always @(posedge clk) begin
    sync_reset[0] <= reset;
  end

  always @(negedge clk) begin
    sync_reset[1] <= sync_reset[0];
  end

  assign rst_sync = sync_reset[1];

endmodule

