module top_module(
  rst,
  wr_clk,
  rd_clk,
  din,
  wr_en,
  rd_en,
  dout,
  full,
  almost_full,
  empty,
  almost_empty,
  rd_data_count,
  wr_data_count,
  prog_full
);input rst;
input wr_clk;
input rd_clk;
input [127 : 0] din;
input wr_en;
input rd_en;
output reg [255 : 0] dout;
output reg full;
output reg almost_full;
output reg empty;
output reg almost_empty;
output reg [10 : 0] rd_data_count;
output reg [11 : 0] wr_data_count;
output reg prog_full;

// FIFO parameters
parameter DEPTH = 2048;
parameter WIDTH = 256; // Output width
reg [127:0] fifo_mem [0:DEPTH-1];
reg [10:0] wr_ptr;
reg [10:0] rd_ptr;
reg [11:0] data_count;

// Write logic
always @(posedge wr_clk or posedge rst) begin
  if (rst) begin
    wr_ptr <= 0;
    data_count <= 0;
    full <= 0;
    almost_full <= 0;
  end else if (wr_en && !full) begin
    fifo_mem[wr_ptr] <= din;
    wr_ptr <= wr_ptr + 1;
    data_count <= data_count + 1;
    if (data_count >= (DEPTH - 1)) full <= 1;
    if (data_count >= (DEPTH - 4)) almost_full <= 1;
  end
end

// Read logic
always @(posedge rd_clk or posedge rst) begin
  if (rst) begin
    rd_ptr <= 0;
    dout <= 0;
    empty <= 1;
    almost_empty <= 0;
  end else if (rd_en && !empty) begin
    dout <= {fifo_mem[rd_ptr], fifo_mem[rd_ptr + 1]}; // Concatenating two 128-bit inputs
    rd_ptr <= rd_ptr + 2;
    data_count <= data_count - 1;
    if (data_count == 0) empty <= 1;
    if (data_count <= 4) almost_empty <= 1;
  end
end

// Update data counts
always @(posedge wr_clk or posedge rst) begin
  if (rst) begin
    rd_data_count <= 0;
    wr_data_count <= 0;
  end else begin
    rd_data_count <= data_count;
    wr_data_count <= data_count;
  end
end

// Program full logic
always @(data_count) begin
  prog_full = (data_count >= 3073);
end

endmodule

