module top_module(
    input [11:0] Data,
    input WrClock,
    input RdClock,
    input WrEn,
    input RdEn,
    input Reset,
    input RPReset,
    output reg [11:0] Q,
    output reg Empty,
    output reg Full,
    output reg AlmostEmpty,
    output reg AlmostFull
);reg [11:0] mem[0:8191];
    reg [12:0] head = 13'h0;
    reg [12:0] tail = 13'h0;
    reg [12:0] count = 13'h0;

    always @(posedge WrClock) begin
        if (Reset || RPReset) begin
            head <= 13'h0;
            tail <= 13'h0;
            count <= 13'h0;
        end else if (WrEn && !Full) begin
            mem[head] <= Data;
            head <= (head == 13'h1FFF) ? 13'h0 : head + 1;
            count <= count + 1;
        end
    end

    always @(posedge RdClock) begin
        if (Reset || RPReset) begin
            head <= 13'h0;
            tail <= 13'h0;
            count <= 13'h0;
        end else if (RdEn && !Empty) begin
            Q <= mem[tail];
            tail <= (tail == 13'h1FFF) ? 13'h0 : tail + 1;
            count <= count - 1;
        end
    end

    always @(*) begin
        Empty = (count == 13'h0);
        Full = (count == 13'h1FFF);
        AlmostEmpty = (count <= 13'h1);
        AlmostFull = (count >= 13'h1FFE);
    end

endmodule

