module top_module(
   clk,
   frame,
   leds
);parameter WIDTH=16;
  input wire clk;
  output wire [WIDTH-1:0] frame;
  output wire [3:0] leds;

  reg [WIDTH-1:0] cnt;

  always @(posedge clk) begin
     cnt <= cnt+1;
  end

  assign frame = cnt;

  assign leds = {
    (cnt[3:2] == 2'b00),
    (cnt[3:2] == 2'b01),
    (cnt[3:2] == 2'b10),
    (cnt[3:2] == 2'b11)
  };endmodule

