            if (R_count == 21'd100_0000) begin
                R_count = 21'b0;
                R_dived_clk = ~R_dived_clk;
            end else begin
                R_count = R_count + 21'd1;
            end
        end
    end

endmodule

module wrap_down_counter(
	input clk,
	input reset_n,
	output reg [2:0] q);always @(posedge clk) begin
	if (!reset_n)
		q <= 3'b111;
	else if (q == 3'b000)
		q <= 3'b111;
	else
		q <= q - 1;
end

endmodule

module top_module(
    input wire D,
    input wire SET_ASYNC,
    input wire SLEEP_B,
    input wire NOTIFIER_REG,
    output reg Q
);always @ (posedge NOTIFIER_REG or posedge SLEEP_B)
    begin
        if (SLEEP_B)
            Q <= 1'b0;
        else if (SET_ASYNC)
            Q <= 1'b1;
        else if (NOTIFIER_REG)
            Q <= D;
    end

endmodule

module top_module (
    input wire u,
    input wire v,
    output wire w
);

    assign w = ~(u ^ v);

endmodule

module top_module(
    input clk,
    input reset,
    input parallel_load,
    input shift,
    input [3:0] input_data,
    output reg [3:0] output_data
);reg [3:0] stage1_data;
reg [3:0] stage2_data;

always @(posedge clk) begin
    if (reset) begin
        stage1_data <= 4'b0;
        stage2_data <= 4'b0;
        output_data <= 4'b0;
    end else if (parallel_load) begin
        stage1_data <= input_data;
        stage2_data <= stage1_data;
        output_data <= stage2_data;
    end else if (shift) begin
        stage1_data <= stage2_data << 1;
        stage2_data <= stage1_data;
        output_data <= stage2_data;
    end
end

endmodule

module top_module(
  input clk,
  input rst_n,
  input [31:0] max_val,
  input en,
  output reg [31:0] out
);always @(posedge clk or negedge rst_n)
    if (~rst_n)
      out <= 0;
    else if (en)
      out <= (out == max_val) ? 0 : out + 1;

endmodule

module top_module(
   input [3:0] A,
   input [3:0] B,
   input [1:0] op,
   output reg [3:0] sum,
   output reg [3:0] diff,
   output reg [3:0] prod,
   output reg [3:0] quot
);always @* begin
   case (op)
      2'b00: begin // addition
         sum = A + B;
         diff = 4'b0;
         prod = 4'b0;
         quot = 4'b0;
      end
      2'b01: begin // subtraction
         sum = 4'b0;
         diff = A - B;
         prod = 4'b0;
         quot = 4'b0;
      end
      2'b10: begin // multiplication
         sum = 4'b0;
         diff = 4'b0;
         prod = A * B;
         quot = 4'b0;
      end
      2'b11: begin // division
         sum = 4'b0;
         diff = 4'b0;
         prod = 4'b0;
         if (B == 4'b0) // division by zero
            quot = 4'b0;
         else
            quot = A / B;
      end
      default: begin // invalid op
         sum = 4'b0;
         diff = 4'b0;
         prod = 4'b0;
         quot = 4'b0;
      end
   endcase
end

endmodule

